// Chart helpers over benchmarks.json (generated by bench/site-data.ts from the committed results).
import data from './benchmarks.json';

export type Tool = (typeof data.projects)[number]['tools'][number];
export type Project = (typeof data.projects)[number];
/** 0 cold, 1 warm, 2 no-op, or combined disk. */
export type Metric = 0 | 1 | 2 | 'disk';

export const benchmarks = data;
export const projects: Project[] = data.projects;
/** Repositories whose measurements are still running. */
export const pending: string[] = (data as { pending?: string[] }).pending ?? [];

export const scenarios = [
  { key: 0, label: 'Cold install', title: 'Cold install, with a lockfile', description: 'Empty package cache · no node_modules · prepared lockfile' },
  { key: 1, label: 'Warm cache', title: 'Fresh checkout, warm cache', description: 'Packages already cached · node_modules rebuilt' },
  { key: 2, label: 'No-op', title: 'Everything already up to date', description: 'Keep cache and node_modules · reinstall after nothing changed' },
] as const;

export function value(tool: Tool, metric: Metric): number | null {
  if (metric === 'disk') return tool.disk?.total ?? null;
  return tool.times?.[metric] ?? null;
}

/** `8.9ms`, `577ms`, `7.21s`, `196.89s`. */
export function seconds(s: number): string {
  if (s < 0.01) return `${(s * 1000).toFixed(1)}ms`;
  if (s < 1) return `${Math.round(s * 1000)}ms`;
  return `${s.toFixed(2)}s`;
}

/** `902 MiB`, `2.53 GiB`. */
export function mebibytes(m: number): string {
  return m < 1024 ? `${Math.round(m)} MiB` : `${(m / 1024).toFixed(2)} GiB`;
}

export function format(v: number, metric: Metric): string {
  return metric === 'disk' ? mebibytes(v) : seconds(v);
}

/** The axis end: the largest value rounded up to 1, 2 or 5 × 10ⁿ. */
export function ceiling(max: number): number {
  const magnitude = 10 ** Math.floor(Math.log10(max));
  for (const step of [1, 2, 2.5, 5, 10]) if (step * magnitude >= max) return step * magnitude;
  return 10 * magnitude;
}

/** How the tool got the lockfile it was timed with. */
export function lockNote(tool: Tool, project: Project): string {
  switch (tool.lockSource) {
    case 'original': return `the project's own ${project.originalLock}`;
    case 'migrated': return `migrated from ${project.originalLock}`;
    case 'imported': return `pnpm import from ${project.originalLock}`;
    default: return 'resolved without a lockfile of its own: versions can differ';
  }
}

export function lockTag(tool: Tool): string | undefined {
  return tool.lockSource === 'fresh' ? 'fresh resolve' : tool.lockSource === 'imported' ? 'imported lock' : undefined;
}

/** fnpm against Bun for one metric, or undefined when either has no value. */
export function versusBun(project: Project, metric: Metric): string | undefined {
  const fnpm = project.tools.find((t) => t.name === 'fnpm');
  const bun = project.tools.find((t) => t.name === 'bun');
  const a = fnpm && value(fnpm, metric);
  const b = bun && value(bun, metric);
  if (!a || !b) return undefined;
  if (metric === 'disk') {
    const diff = Math.abs(1 - a / b) * 100;
    return a <= b ? `fnpm used ${diff.toFixed(1)}% less disk than Bun` : `fnpm used ${diff.toFixed(1)}% more disk than Bun`;
  }
  return a <= b ? `${(b / a).toFixed(2)}× faster than Bun in this snapshot` : `${(a / b).toFixed(2)}× Bun's duration in this snapshot`;
}

export function fastest(project: Project, metric: Metric): Tool | undefined {
  return project.tools
    .filter((t) => value(t, metric) != null)
    .sort((x, y) => value(x, metric)! - value(y, metric)!)[0];
}

export const measuredDate = new Date(`${data.measured}T00:00:00Z`).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });
